import { createSignal } from 'solid-js';

// ❌ OLD: This expression runs once when the component sets up.
// It is NOT reactive — doubling never updates when count changes,
// because plain JS has no tracking. The JSX below shows a stale 0.
function Double() {
  const [count, setCount] = createSignal(0);
  const doubled = count() * 2; // ❌ OLD: computed once, frozen at 0

  return (
    <>
      <p>{doubled}</p> {/* stays 0 forever */}
      <button onClick={() => setCount(count() + 1)}>+1</button>
    </>
  );
}

// To make it reactive you'd have to inline the expression in JSX
// (count() * 2) so the compiler wraps it in its own computation.

import { createSignal, createMemo } from 'solid-js';

// ✅ NEW: createMemo caches the derived value, marks it dirty when
// count changes, and recomputes lazily on the next read. Multiple
// JSX nodes can read doubled() with a single recomputation.
function Double() {
  const [count, setCount] = createSignal(0);
  const doubled = createMemo(() => count() * 2); // ✅ NEW: lazy + cached

  return (
    <>
      <p>{doubled()}</p> {/* ✅ NEW: reads the cached/recomputed value */}
      <p>{doubled()}</p> {/* second read: same cached value, no recompute */}
      <button onClick={() => setCount(count() + 1)}>+1</button>
    </>
  );
}
